import campusJson from './campus.json' with { type: 'json' };
import { createMapIndex } from './query';
import type { CampusMap } from './schema';

/**
 * The campus map. Generated by `pnpm map:build` (tools/map-tools) and checked against the schema
 * by the test suite rather than at import time, so the browser bundle does not pay for it.
 */
export const campusMap = campusJson as unknown as CampusMap;

/** Shared lookup index for {@link campusMap}. */
export const campusIndex = createMapIndex(campusMap);
